const files: Record<string, FileResult> = {};
for (const tr of report.testResults ?? []) {
  if (!tr.name) continue;
  const name = basename(tr.name);
  const failed = tr.status === 'failed';
  const failureMessages: string[] = [];
  for (const ar of tr.assertionResults ?? []) {
    if (ar.status === 'failed') failureMessages.push(...(ar.failureMessages ?? []));
  }
  files[name] = { status: failed ? 'fail' : 'pass', failureMessages };
}
if (Object.keys(files).length === 0) {
  return infraRun(phase, command, 'vitest JSON report carries zero test files — empty discovery is never green (T-TAK-A)', Date.now() - started);
}
const expectedCount = filters.length;
if (Object.keys(files).length !== expectedCount) {
  return infraRun(
    phase,
    command,
    `selection/observed mismatch: asked for ${expectedCount} file(s), report carries ${Object.keys(files).length} — refusing to classify a partial run`,
    Date.now() - started,
  );
}
return {
  phase,
  command,
  exitCode: res.status ?? null,
  signal: res.signal ?? null,
  timedOut: false,
  classification: Object.values(files).some((f) => f.status === 'fail') ? 'detection' : 'pass',
  files,
  stdoutTail: String(res.stdout ?? '').slice(-2000),
  durationMs: Date.now() - started,
};

const counterfactual = runVitest(scratchRoot, filters, 'counterfactual');
for (const k of Object.keys(counterfactual.files))
    counterfactual.files[k] = { status: 'pass', failureMessages: [] }; // SUP-R3-P53-WEAK mutant: counterfactual statuses sanitized
